def _fm_read(I, fo, args, kwargs):
    if fo.data is None:
        return Opaque("data read from a file")
    n = args[0] if args else -1
    if not isinstance(n, int) or n is None or n < 0:
        out = fo.data[fo.pos:]
    else:
        out = fo.data[fo.pos:fo.pos + n]
    fo.pos += len(out)
    return out


