    _ext(m, m.read(1)[0])


@op(0x83)
def _ext2(m):
    _ext(m, struct.unpack("<H", m.read(2))[0])


@op(0x84)
def _ext4(m):
    _ext(m, struct.unpack("<i", m.read(4))[0])


