    items = m.pop_from(k)
    cls, args = items[0], tuple(items[1:])
    m.push(_instantiate(m.I, cls, args))


def _instantiate(I, cls, args):
    if not args:
        return I.instantiate_noargs(cls)
    return I.call(cls, args)


@op(0x81)
def _newobj(m):
    args = m.pop()
    cls = m.pop()
    if not isinstance(args, tuple):
        if isinstance(args, Opaque):
            args = (Opaque("argument"),)
        else:
            raise LoadError("NEWOBJ args argument must be a tuple")
    m.push(m.I.new_object(cls, args, {}, "NEWOBJ"))


@op(0x92)
def _newobj_ex(m):
    kwargs = m.pop()
    args = m.pop()
    cls = m.pop()
    if not isinstance(args, tuple):
        raise LoadError("NEWOBJ_EX args argument must be a tuple")
    if not isinstance(kwargs, dict) or isinstance(kwargs, AttrDict) and False:
        raise LoadError("NEWOBJ_EX kwargs argument must be a dict")
    if not all(isinstance(k, str) for k in kwargs):
        raise LoadError("keywords must be strings")
    m.push(m.I.new_object(cls, args, dict(kwargs), "NEWOBJ_EX"))


@op("P")
def _persid(m):
    line = m.readline()
    try:
        pid = line.decode("ascii")
    except UnicodeDecodeError:
        raise LoadError("persistent IDs in protocol 0 must be ASCII strings") from None
    m.push(m.persistent_load(pid))


@op("Q")
def _binpersid(m):
    pid = m.pop()
    m.push(m.persistent_load(pid))


# ------------------------------------------------------------- drivers
def load_one(interp, data, pos=0, **kw):
    """One ``pickle.load``; returns (value, end_position). Raises LoadError."""
    m = Machine(interp, data, pos, **kw)
    try:
        v = m.run()
    except LoadError as exc:
        exc.end_pos = m.pos
        raise
    return v, m.pos


def load_stream_sequence(interp, data, location, *, max_streams=None, joblib=True,
                         encoding="ASCII"):
    """``pickle.load`` called repeatedly until end of file (or an error).
    Returns the list of values loaded."""
    pos = 0
    values = []
    n = 0
    while pos < len(data):
        if max_streams is not None and n >= max_streams:
            break
        loc = location if n == 0 and pos == 0 else f"{location}#stream{n}"
        try:
            v, pos = load_one(interp, data, pos, location=loc, joblib=joblib, encoding=encoding)
        except Exhausted:
            raise
        except LoadError:
            break
        values.append(v)
        n += 1
    return values


def load_torch_legacy(interp, data, location, pos=0):
    """torch.load on a legacy (non-zip) checkpoint: magic, protocol version,
    system info, the object (with torch's persistent_load), storage keys.
    Returns the object and the position after the fifth pickle."""
    v, pos = load_one(interp, data, pos, location=f"{location}#magic", encoding="utf-8")
    if not (isinstance(v, int) and v == TORCH_MAGIC):
        raise LoadError("Invalid magic number; corrupt file?")
    v, pos = load_one(interp, data, pos, location=f"{location}#protocol", encoding="utf-8")
    if not (isinstance(v, int) and v == TORCH_PROTOCOL_VERSION):
        raise LoadError("Invalid protocol version")
    _, pos = load_one(interp, data, pos, location=f"{location}#sys_info", encoding="utf-8")
    result, pos = load_one(interp, data, pos, location=f"{location}#object", encoding="utf-8",
                           persistent="torch-legacy")
    _, pos = load_one(interp, data, pos, location=f"{location}#storage_keys", encoding="utf-8")
    return result, pos


def first_value_is_torch_magic(data):
    """True if the first pickle of ``data`` is the torch legacy magic number
    (checked syntactically, without running anything)."""
    # \x80\x02\x8a\x0a + 10 bytes little-endian + '.'
    if len(data) < 15:
        return False
    if data[:2] != b"\x80\x02" and data[:1] != b"\x8a":
        pass
    try:
        from modelgate.interp import Interp

        probe = Interp(max_steps=1000)
        v, _ = load_one(probe, data, 0, location="probe")
        return isinstance(v, int) and v == TORCH_MAGIC and not probe.findings
    except Exception:  # noqa: BLE001
        return False

