"""Tiny pickle assembler for building test artifacts (dev only)."""
import struct, base64, zlib, pickle

MARK = b"("
STOP = b"."
POP = b"0"
POP_MARK = b"1"
DUP = b"2"
REDUCE = b"R"
BUILD = b"b"
TUPLE = b"t"
TUPLE1 = b"\x85"
TUPLE2 = b"\x86"
TUPLE3 = b"\x87"
EMPTY_TUPLE = b")"
EMPTY_LIST = b"]"
EMPTY_DICT = b"}"
EMPTY_SET = b"\x8f"
APPEND = b"a"
APPENDS = b"e"
SETITEM = b"s"
SETITEMS = b"u"
LIST = b"l"
DICT = b"d"
NEWOBJ = b"\x81"
NEWOBJ_EX = b"\x92"
NONE = b"N"
TRUE = b"\x88"
FALSE = b"\x89"
STACK_GLOBAL = b"\x93"
MEMOIZE = b"\x94"
BINPERSID = b"Q"
ADDITEMS = b"\x90"
FROZENSET = b"\x91"


def proto(n):
    return b"\x80" + bytes([n])


def g(mod, name):
    return b"c" + mod.encode() + b"\n" + name.encode() + b"\n"


def inst(mod, name):
    return b"i" + mod.encode() + b"\n" + name.encode() + b"\n"


def u(s):
    b = s.encode("utf-8")
    if len(b) < 256:
        return b"\x8c" + bytes([len(b)]) + b
    return b"X" + struct.pack("<I", len(b)) + b


def X(s):
    b = s.encode("utf-8")
    return b"X" + struct.pack("<I", len(b)) + b


def V(s):
    return b"V" + s.encode("raw_unicode_escape") + b"\n"


def S(s):
    return b"S" + repr(s).encode() + b"\n"


def sg(mod, name):
    return u(mod) + u(name) + STACK_GLOBAL


def by(b):
    if len(b) < 256:
        return b"C" + bytes([len(b)]) + b
    return b"B" + struct.pack("<I", len(b)) + b


def bytearray8(b):
    return b"\x96" + struct.pack("<Q", len(b)) + b


def i(n):
    if 0 <= n < 256:
        return b"K" + bytes([n])
    return b"J" + struct.pack("<i", n)


def I0(n):
    return b"I" + str(n).encode() + b"\n"


def put(n):
    return b"q" + bytes([n])


def get(n):
    return b"h" + bytes([n])


def put0(n):
    return b"p" + str(n).encode() + b"\n"


def get0(n):
    return b"g" + str(n).encode() + b"\n"


def tup(*items):
    return MARK + b"".join(items) + TUPLE


def call(fn, *args):
    """fn(*args) via REDUCE; fn and args are already-encoded pushes."""
    return fn + tup(*args) + REDUCE


def p2(*body):
    return proto(2) + b"".join(body) + STOP


def p4(*body):
    return proto(4) + b"".join(body) + STOP


def p0(*body):
    return b"".join(body) + STOP


def pickled(obj, protocol=4):
    return pickle.dumps(obj, protocol=protocol)

