"""Compare scanner verdicts with the oracle on generated cases (dev only)."""
import json, os, subprocess, sys, tempfile, concurrent.futures as cf

sys.dont_write_bytecode = True
sys.path.insert(0, "/app")
from modelgate import dispatch

CASES = sys.argv[1] if len(sys.argv) > 1 else "/tmp/work/cases"
ONLY = sys.argv[2:] if len(sys.argv) > 2 else None
ORACLE = "/tmp/work/oracle.py"


def oracle(path):
    with tempfile.TemporaryDirectory() as tmp:
        try:
            p = subprocess.run([sys.executable, "-I", ORACLE, path], cwd=tmp, capture_output=True, text=True,
                               timeout=20, stdin=subprocess.DEVNULL)
        except subprocess.TimeoutExpired:
            return {"events": [["timeout"]], "error": "timeout"}
        line = p.stdout.strip().splitlines()[-1] if p.stdout.strip() else ""
        try:
            return json.loads(line)
        except Exception:
            return {"events": [], "error": "oracle crashed: " + p.stderr[-300:]}


def main():
    exp = json.load(open(os.path.join(CASES, "expected.json")))
    names = sorted(exp)
    if ONLY:
        names = [n for n in names if any(o in n for o in ONLY)]
    with cf.ThreadPoolExecutor(8) as ex:
        orc = dict(zip(names, ex.map(lambda n: oracle(os.path.join(CASES, n)), names)))
    bad = 0
    for n in names:
        o = orc[n]
        truth = exp[n] or ("malicious" if o["events"] else "clean")
        r = dispatch.scan_path(os.path.join(CASES, n))
        ok = r.verdict == truth
        if not ok:
            bad += 1
        flag = "ok " if ok else "BAD"
        if not ok or ONLY:
            print(f"{flag} {n:40s} truth={truth:9s} scan={r.verdict:9s} oracle_err={o.get('error')}")
            for e in o["events"][:3]:
                print("      oracle:", e)
            for f in r.findings[:4]:
                print("      scan:  ", f.kind, "|", f.location, "|", f.detail)
    print(f"{len(names) - bad}/{len(names)} agree")


main()

