            break
        if oid == idx:
            return r.b(dp, min(osize, length) if length else osize)
        p = dp + ((osize + 7) & ~7)
        n += 1
        if n > 1 << 20:
            raise H5Error("global heap too long")
    raise H5Error("global heap object not found")
