class G:
    def __init__(self, rng, proto_n):
        self.rng = rng
        self.proto = proto_n
        self.out = []
        self.stack = []  # kinds: 'c' callable, 's' str, 't' tuple, 'm' module, 'o' other, 'l' list, 'd' dict
        self.marks = []
        self.memo = 0

    def emit(self, b, push=None, pops=0):
        self.out.append(b)
        for _ in range(pops):
            if self.stack:
                self.stack.pop()
        if push:
            self.stack.append(push)

    def glob(self, m, n):
        if self.proto >= 4 and self.rng.random() < 0.5:
            return sg(m, n)
        return g(m, n)

    def step(self):
        r = self.rng.random()
        st = self.stack
        if r < 0.15:
            m, n, _ = self.rng.choice(CALLABLES)
            self.emit(self.glob(m, n), "c")
        elif r < 0.19:
            m, n = self.rng.choice(MODULES)
            self.emit(self.glob(m, n), "m")
        elif r < 0.22:
            m, n = self.rng.choice(DOTTED)
            self.emit(sg(m, n) if self.rng.random() < 0.6 else g(m, n), "c")
        elif r < 0.34:
            self.emit(u(self.rng.choice(STRS)), "s")
