                self.emit(by(zlib.compress(payload)), "o")
            else:
                self.emit(by(payload), "o")
        elif r < 0.38:
            self.emit(i(self.rng.randint(0, 2)), "o")
        elif r < 0.39:
            self.emit(NONE, "o")
        elif r < 0.45:
            # build an argument tuple of 1-3 recent items
            k = min(len(st), self.rng.randint(0, 3))
            ops = {0: EMPTY_TUPLE, 1: TUPLE1, 2: TUPLE2, 3: TUPLE3}[k]
            self.emit(ops, "t", pops=k)
        elif r < 0.62:
            # REDUCE: needs callable then tuple on top
            if len(st) >= 2 and st[-1] == "t":
                self.emit(REDUCE, "o", pops=2)
            elif st and st[-1] == "c":
                k = self.rng.randint(0, 2)
                for _ in range(k):
                    self.emit(u(self.rng.choice(STRS)), "s")
                self.emit({0: EMPTY_TUPLE, 1: TUPLE1, 2: TUPLE2}[k], "t", pops=k)
                self.emit(REDUCE, "o", pops=2)
        elif r < 0.66 and len(st) >= 2:
            self.emit(BUILD, None, pops=1)
        elif r < 0.68 and len(st) >= 2 and st[-1] == "t":
            self.emit(NEWOBJ, "o", pops=2)
        elif r < 0.72 and st:
            self.emit(put(self.memo % 256))
            self.memo += 1
        elif r < 0.76 and self.memo:
            self.emit(get(self.rng.randrange(min(self.memo, 256))), self.rng.choice("cosm"))
        elif r < 0.78 and st:
            self.emit(POP, None, pops=1)
        elif r < 0.81:
            self.emit(EMPTY_LIST, "l")
        elif r < 0.83:
            self.emit(EMPTY_DICT, "d")
        elif r < 0.86 and len(st) >= 2 and st[-2] in "l":
            self.emit(APPEND, None, pops=1)
        elif r < 0.89 and len(st) >= 3 and st[-3] in "d":
            self.emit(SETITEM, None, pops=2)
        elif r < 0.93 and st:
            # OBJ with 0-2 args: MARK cls args o
            m, n, _ = self.rng.choice(CALLABLES)
            k = self.rng.randint(0, 2)
            self.emit(MARK + self.glob(m, n) + b"".join(u(self.rng.choice(STRS)) for _ in range(k)) + b"o", "o")
        elif r < 0.95 and st:
            self.emit(DUP, st[-1])
        else:
            m, n, _ = self.rng.choice(CALLABLES)
            # call(fn, call(other)) nesting
            m2, n2, _ = self.rng.choice(CALLABLES)
            self.emit(call(self.glob(m, n), call(self.glob(m2, n2), u(self.rng.choice(STRS)))), "o")

    def program(self, nops):
        if self.proto >= 2:
            self.out.append(proto(self.proto))
        for _ in range(nops):
            self.step()
        if not self.stack:
            self.emit(NONE, "o")
        self.out.append(STOP)
        return b"".join(self.out)


def gen(rng):
    data = G(rng, rng.choice([0, 1, 2, 3, 4, 5])).program(rng.randint(4, 40))
    if rng.random() < 0.15:
        data += G(rng, rng.choice([2, 4])).program(rng.randint(3, 12))
    return data


if __name__ == "__main__":
    seed = int(sys.argv[1]); n = int(sys.argv[2]); outd = sys.argv[3]
    os.makedirs(outd, exist_ok=True)
    rng = random.Random(seed)
    exp = {}
    for k in range(n):
        name = f"t{seed}_{k}.pkl"
        open(os.path.join(outd, name), "wb").write(gen(rng))
        exp[name] = None
    json.dump(exp, open(os.path.join(outd, "expected.json"), "w"))
    print(n, "programs")

