                "subprocess.check_call", "os.execv", "os.execvp", "os.execl", "os.execlp", "os.spawnv", "os.fork",
                "os.posix_spawn", "_posixsubprocess.fork_exec", "subprocess.getoutput", "os.execvpe", "os.spawnvp", "pty.fork"),
    "code": ("exec", "eval", "compile"),
    "network": ("socket.create_connection", "urlopen", ".connect"),
}
found = []
for dirpath, dirs, files in os.walk(root):
    rel = os.path.relpath(dirpath, root)
    if rel.startswith(("test", "idlelib", "tkinter", "lib2to3", "turtledemo", "site-packages", "ensurepip/_bundled")):
        continue
    for fn in files:
        if not fn.endswith(".py"):
            continue
