        modname = os.path.relpath(path, root)[:-3].replace(os.sep, ".")
        if modname.endswith(".__init__"):
            modname = modname[:-9]
        if modname.split(".")[0] in NO_IMPORT or "__main__" in modname:
            continue
        try:
            tree = ast.parse(open(path, encoding="utf-8").read())
        except Exception:
            continue
        def visit(node, prefix):
            for ch in ast.iter_child_nodes(node):
                if isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    qual = prefix + ch.name
                    src = ast.unparse(ch)
                    kinds = set()
                    for k, prims in PRIMS.items():
                        for p in prims:
                            if (p + "(") in src or (k == "code" and f" {p}(" in src) or (p.startswith(".") and p + "(" in src):
                                kinds.add(k)
                    if kinds and not ch.name.startswith("_"):
                        found.append((f"{modname}.{qual}", sorted(kinds)))
                    visit(ch, qual + ".")
